-- NavNet PostgreSQL schema (reference DDL).
-- The source of truth is server/prisma/schema.prisma; `prisma migrate dev` generates the real migration.
-- This file is for reading and for running against a bare Postgres without Prisma.

CREATE TYPE "Role" AS ENUM ('ADMIN','USER');
CREATE TYPE "TripStatus" AS ENUM ('PLANNED','ACTIVE','PAUSED','COMPLETED','CANCELLED');
CREATE TYPE "MemberStatus" AS ENUM ('ACTIVE','REMOVED','LEFT');
CREATE TYPE "CheckpointCategory" AS ENUM ('BREAKFAST','FUEL','HYDRATION','LUNCH','REST','SCENIC','HOTEL','HOSPITAL','OTHER');
CREATE TYPE "VehicleType" AS ENUM ('BIKE','CAR','BICYCLE','BUS','WALKING','MIXED');
CREATE TYPE "MessageType" AS ENUM ('CHAT','ANNOUNCEMENT','SYSTEM','VOICE');
CREATE TYPE "AlertType" AS ENUM ('SOS','OFF_ROUTE','STATIONARY','OFFLINE','LOW_BATTERY','OVERSPEED','WRONG_DIRECTION','GAP','STOP_REQUEST');
CREATE TYPE "AlertSeverity" AS ENUM ('INFO','WARNING','CRITICAL');
CREATE TYPE "JoinStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TABLE "User"(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, role "Role" NOT NULL DEFAULT 'USER', phone TEXT, "vehicleNumber" TEXT, "bloodGroup" TEXT, "emergencyName" TEXT, "emergencyPhone" TEXT, "medicalNotes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Community"(id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL, city TEXT, category TEXT NOT NULL DEFAULT 'General', "coverImage" TEXT, "isPublic" BOOLEAN NOT NULL DEFAULT true, "ownerId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CommunityMember"(id TEXT PRIMARY KEY, "communityId" TEXT NOT NULL REFERENCES "Community"(id) ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, status "JoinStatus" NOT NULL DEFAULT 'PENDING', message TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "decidedAt" TIMESTAMP(3), UNIQUE("communityId","userId"));
CREATE TABLE "CommunityAnnouncement"(id TEXT PRIMARY KEY, "communityId" TEXT NOT NULL REFERENCES "Community"(id) ON DELETE CASCADE, "authorId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Trip"(id TEXT PRIMARY KEY, "groupCode" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, "imageUrl" TEXT, "adminId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "leaderId" TEXT REFERENCES "User"(id) ON DELETE SET NULL, "sweepId" TEXT, "communityId" TEXT REFERENCES "Community"(id) ON DELETE SET NULL, "startName" TEXT NOT NULL, "startLat" DOUBLE PRECISION NOT NULL, "startLng" DOUBLE PRECISION NOT NULL, "destName" TEXT NOT NULL, "destLat" DOUBLE PRECISION NOT NULL, "destLng" DOUBLE PRECISION NOT NULL, "routeGeometry" JSONB NOT NULL, "routeDistance" DOUBLE PRECISION NOT NULL, "routeDuration" DOUBLE PRECISION NOT NULL, "routeProvider" TEXT NOT NULL DEFAULT 'osrm', "maxMembers" INTEGER NOT NULL DEFAULT 20, "vehicleType" "VehicleType" NOT NULL DEFAULT 'BIKE', "speedLimitKmh" INTEGER NOT NULL DEFAULT 80, "gapAlertMeters" INTEGER NOT NULL DEFAULT 1500, "meetLat" DOUBLE PRECISION, "meetLng" DOUBLE PRECISION, "meetName" TEXT, "meetSetAt" TIMESTAMP(3), "departAt" TIMESTAMP(3), pois JSONB, "poisAt" TIMESTAMP(3), "departureTime" TIMESTAMP(3) NOT NULL, "expectedArrival" TIMESTAMP(3) NOT NULL, status "TripStatus" NOT NULL DEFAULT 'PLANNED', "startedAt" TIMESTAMP(3), "pausedAt" TIMESTAMP(3), "endedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Waypoint"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "order" INTEGER NOT NULL, name TEXT NOT NULL, lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL);
CREATE TABLE "Checkpoint"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "order" INTEGER NOT NULL, name TEXT NOT NULL, category "CheckpointCategory" NOT NULL DEFAULT 'OTHER', lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, eta TIMESTAMP(3));
CREATE TABLE "TripMember"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, status "MemberStatus" NOT NULL DEFAULT 'ACTIVE', "vehicleNumber" TEXT, "joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastLat" DOUBLE PRECISION, "lastLng" DOUBLE PRECISION, "lastSpeed" DOUBLE PRECISION, "lastHeading" DOUBLE PRECISION, battery INTEGER, "lastSeenAt" TIMESTAMP(3), checklist JSONB, "readyAt" TIMESTAMP(3), "progressMeters" DOUBLE PRECISION NOT NULL DEFAULT 0, "maxProgressMeters" DOUBLE PRECISION NOT NULL DEFAULT 0, "arrivedAt" TIMESTAMP(3), UNIQUE("tripId","userId"));
CREATE TABLE "LocationPing"(id BIGSERIAL PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, speed DOUBLE PRECISION, heading DOUBLE PRECISION, accuracy DOUBLE PRECISION, battery INTEGER, "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CheckpointVisit"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "checkpointId" TEXT NOT NULL REFERENCES "Checkpoint"(id) ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "visitedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("checkpointId","userId"));
CREATE TABLE "Message"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "senderId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "recipientId" TEXT REFERENCES "User"(id) ON DELETE CASCADE, type "MessageType" NOT NULL DEFAULT 'CHAT', body TEXT NOT NULL, "audioUrl" TEXT, "durationMs" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Alert"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "userId" TEXT REFERENCES "User"(id) ON DELETE SET NULL, type "AlertType" NOT NULL, severity "AlertSeverity" NOT NULL DEFAULT 'WARNING', message TEXT NOT NULL, data JSONB, lat DOUBLE PRECISION, lng DOUBLE PRECISION, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "acknowledgedAt" TIMESTAMP(3));
CREATE TABLE "TripReport"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL UNIQUE REFERENCES "Trip"(id) ON DELETE CASCADE, summary JSONB NOT NULL, "generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Expense"(id TEXT PRIMARY KEY, "tripId" TEXT NOT NULL REFERENCES "Trip"(id) ON DELETE CASCADE, "paidById" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "amountPaise" INTEGER NOT NULL, description TEXT NOT NULL, "splitAmong" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
